const { withAppBuildGradle } = require('expo/config-plugins');

// android/ is regenerated by `expo prebuild` (it's gitignored — see .gitignore),
// so hand-editing build.gradle doesn't survive a clean prebuild. This plugin
// re-applies the release signingConfig every time so the wiring is tracked in
// git instead of living only in a throwaway native folder.
//
// Credentials never enter git. `project.hasProperty(...)` guards the block so
// the release build type falls back to debug signing when the four
// MYAPP_UPLOAD_* gradle properties aren't defined — which is the case on any
// machine (or CI runner) without the upload keystore. Real values go in
// ~/.gradle/gradle.properties (untracked, per the drill) or are injected as
// EAS Build secrets.
const MARKER = '// @generated by with-android-release-signing';

function insertReleaseSigningConfig(contents) {
  if (contents.includes(MARKER)) return contents;

  const debugSigningConfigBlock = /(signingConfigs\s*\{\s*debug\s*\{[^}]*\}\s*)(\})/;
  if (!debugSigningConfigBlock.test(contents)) {
    throw new Error(
      'with-android-release-signing: could not find `signingConfigs { debug { ... } }` in android/app/build.gradle to anchor the release block on.'
    );
  }

  contents = contents.replace(
    debugSigningConfigBlock,
    `$1
        release {
            ${MARKER}
            if (project.hasProperty('MYAPP_UPLOAD_STORE_FILE')) {
                storeFile file(MYAPP_UPLOAD_STORE_FILE)
                storePassword MYAPP_UPLOAD_STORE_PASSWORD
                keyAlias MYAPP_UPLOAD_KEY_ALIAS
                keyPassword MYAPP_UPLOAD_KEY_PASSWORD
            }
        }
    $2`
  );

  contents = contents.replace(
    /release\s*\{(\s*)(\/\/ Caution![^\n]*\n\s*\/\/ see[^\n]*\n\s*)signingConfig signingConfigs\.debug/,
    `release {$1$2signingConfig project.hasProperty('MYAPP_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`
  );

  return contents;
}

const withAndroidReleaseSigning = (config) =>
  withAppBuildGradle(config, (config) => {
    if (config.modResults.language !== 'groovy') {
      throw new Error('with-android-release-signing only supports Groovy build.gradle files');
    }
    config.modResults.contents = insertReleaseSigningConfig(config.modResults.contents);
    return config;
  });

module.exports = withAndroidReleaseSigning;
